function ifScript() {
    const query_parameter = `filter=name eq 'PRSNL_${current.variables.requested_for.email.split('@')[0].replace(/\./g, '_').toUpperCase().slice(0, 22)}'`;
	const containers = new x_xal_idconnect.XalientUtilitiesCatalogItem().cya_scim_get("containers",query_parameter);
	const resb_containers = JSON.parse(containers.getBody());
    if (resb_containers.totalResults > 0) {
        return 'yes';
    }
    return 'no';
}

answer = ifScript();

function ifScript() {
    const query_parameter = `filter=name eq 'PRSNL_${current.variables.requested_for.email.split('@')[0].replace(/\./g, '_').toUpperCase().slice(0, 22)}'`;
	const containers = new x_xal_idconnect.XalientUtilitiesCatalogItem().cya_scim_get("containers",query_parameter);
	const resb_containers = JSON.parse(containers.getBody());
    if (resb_containers.totalResults > 0) {
        return 'yes';
    }
    return 'no';
}

